INSERT INTO public.diag_questions (instrument_id, dimension_id, code, text, weight, direction, allow_na, active, sort_order) VALUES ('11111111-1111-4111-8111-000000000001', (SELECT id FROM public.diag_dimensions WHERE instrument_id='11111111-1111-4111-8111-000000000001' AND code='R'), 'R04', 'O crescimento da empresa ocorre de forma financeiramente sustentável.', 3, 'direct', true, true, 67);
