INSERT INTO public.diag_questions (instrument_id, dimension_id, code, text, weight, direction, allow_na, active, sort_order) VALUES ('11111111-1111-4111-8111-000000000001', (SELECT id FROM public.diag_dimensions WHERE instrument_id='11111111-1111-4111-8111-000000000001' AND code='R'), 'R07', 'A empresa possui condições de sustentar seu modelo de negócio no médio e longo prazo.', 3, 'direct', true, true, 70);
INSERT INTO public.diag_stage_profiles (instrument_id, code, name, short_label, sort_order, axes, is_critical, auto_release_allowed, narrative) VALUES ('11111111-1111-4111-8111-000000000001', 'namoro', 'Namoro', 'Ideia e entusiasmo', 1, '{"flexibilidade":85,"controle":20,"integracao":30,"sustentacao":15}'::jsonb, false, true, '{"summary":"Fase de concepção: a empresa é sustentada pela visão e pelo entusiasmo do fundador, com pouca estrutura de gestão e baixa previsibilidade de resultados.","signals":["Decisões centralizadas na visão do fundador","Poucos processos e indicadores formais","Muita energia em ideias, pouca em execução sistemática"],"risks":["Compromisso não se converter em operação real","Recursos consumidos antes de validar a proposta de valor"],"focus":["Traduzir a visão em objetivos concretos de 12 meses","Definir os primeiros indicadores de acompanhamento","Validar diferencial competitivo com clientes reais"]}'::jsonb);
INSERT INTO public.diag_stage_profiles (instrument_id, code, name, short_label, sort_order, axes, is_critical, auto_release_allowed, narrative) VALUES ('11111111-1111-4111-8111-000000000001', 'infancia', 'Infância', 'Ação e sobrevivência', 2, '{"flexibilidade":45,"controle":30,"integracao":35,"sustentacao":35}'::jsonb, false, true, '{"summary":"Fase de operação intensa: a empresa vende e entrega, mas depende fortemente do líder principal, com caixa apertado e gestão reativa.","signals":["Forte dependência do proprietário","Gestão orientada a urgências","Fragilidade financeira e de controles"],"risks":["Esgotamento do líder","Mortalidade por falta de caixa","Crescimento sem base de processos"],"focus":["Organizar controle de custos e rentabilidade","Definir responsabilidades básicas","Criar rotina mínima de acompanhamento de resultados"]}'::jsonb);
INSERT INTO public.diag_stage_profiles (instrument_id, code, name, short_label, sort_order, axes, is_critical, auto_release_allowed, narrative) VALUES ('11111111-1111-4111-8111-000000000001', 'toca_toca', 'Toca-Toca', 'Crescimento acelerado', 3, '{"flexibilidade":90,"controle":40,"integracao":50,"sustentacao":55}'::jsonb, false, true, '{"summary":"Fase de crescimento acelerado e oportunista: muitas frentes abertas, confiança elevada e estrutura que não acompanha o ritmo do negócio.","signals":["Múltiplas oportunidades sem critério de foco","Processos improvisados","Decisões rápidas com pouca análise"],"risks":["Dispersão de foco e recursos","Erros recorrentes por falta de padrão","Armadilha do fundador"],"focus":["Estabelecer prioridades estratégicas e critérios de foco","Formalizar os processos essenciais","Fortalecer gestores intermediários com autonomia"]}'::jsonb);
INSERT INTO public.diag_stage_profiles (instrument_id, code, name, short_label, sort_order, axes, is_critical, auto_release_allowed, narrative) VALUES ('11111111-1111-4111-8111-000000000001', 'adolescencia', 'Adolescência', 'Profissionalização', 4, '{"flexibilidade":75,"controle":65,"integracao":70,"sustentacao":65}'::jsonb, false, true, '{"summary":"Fase de transição para a gestão profissional: sistemas e delegação avançam, com conflitos naturais entre a cultura empreendedora e a necessidade de estrutura.","signals":["Delegação em construção","Conflitos entre áreas e entre fundador e gestores","Indicadores e processos em amadurecimento"],"risks":["Divórcio entre fundador e equipe profissional","Envelhecimento precoce por excesso de controle"],"focus":["Alinhar papéis e limites de decisão","Integrar comunicação entre áreas","Equilibrar controle e agilidade"]}'::jsonb);
INSERT INTO public.diag_stage_profiles (instrument_id, code, name, short_label, sort_order, axes, is_critical, auto_release_allowed, narrative) VALUES ('11111111-1111-4111-8111-000000000001', 'plenitude', 'Plenitude', 'Equilíbrio e vitalidade', 5, '{"flexibilidade":85,"controle":85,"integracao":85,"sustentacao":85}'::jsonb, false, true, '{"summary":"Fase de equilíbrio entre flexibilidade e controle: a empresa cresce com previsibilidade, forma líderes e mantém capacidade de adaptação.","signals":["Resultados consistentes e crescimento sustentável","Processos claros com espaço para inovação","Sucessão e desenvolvimento de pessoas ativos"],"risks":["Acomodação gradual","Perda de senso de urgência"],"focus":["Preservar a disposição para mudar","Renovar a estratégia periodicamente","Investir em novos negócios e talentos"]}'::jsonb);
INSERT INTO public.diag_stage_profiles (instrument_id, code, name, short_label, sort_order, axes, is_critical, auto_release_allowed, narrative) VALUES ('11111111-1111-4111-8111-000000000001', 'estabilidade', 'Estabilidade', 'Conforto e previsibilidade', 6, '{"flexibilidade":60,"controle":85,"integracao":80,"sustentacao":85}'::jsonb, false, true, '{"summary":"Fase de conforto: resultados ainda são bons e a estrutura funciona, mas a empresa começa a perder apetite por mudança e proximidade com o mercado.","signals":["Foco em manutenção do que existe","Menor investimento em novas ideias","Reuniões mais sobre passado do que sobre futuro"],"risks":["Início silencioso do envelhecimento","Perda de talentos inquietos"],"focus":["Reaproximar a empresa do cliente e do mercado","Recriar espaço para experimentação","Estabelecer metas de renovação"]}'::jsonb);
INSERT INTO public.diag_stage_profiles (instrument_id, code, name, short_label, sort_order, axes, is_critical, auto_release_allowed, narrative) VALUES ('11111111-1111-4111-8111-000000000001', 'aristocracia', 'Aristocracia', 'Forma acima do conteúdo', 7, '{"flexibilidade":35,"controle":90,"integracao":65,"sustentacao":75}'::jsonb, false, true, '{"summary":"Fase em que a aparência e a tradição pesam mais que o desempenho: controles fortes, pouca inovação e distância crescente do mercado.","signals":["Excesso de formalismo","Dificuldade de mudar práticas antigas","Perda gradual de competitividade"],"risks":["Erosão financeira mascarada por reservas","Ruptura cultural quando os resultados caem"],"focus":["Confrontar dados de mercado e rentabilidade","Reduzir camadas de controle sem valor","Retomar iniciativa comercial e inovação"]}'::jsonb);
INSERT INTO public.diag_stage_profiles (instrument_id, code, name, short_label, sort_order, axes, is_critical, auto_release_allowed, narrative) VALUES ('11111111-1111-4111-8111-000000000001', 'pre_burocracia', 'Pré-Burocracia / Recriminação', 'Conflito interno', 8, '{"flexibilidade":25,"controle":65,"integracao":30,"sustentacao":45}'::jsonb, true, false, '{"summary":"Fase de recriminação: os resultados caem e a energia se volta para dentro — busca de culpados, conflitos e perda de confiança entre liderança e equipe.","signals":["Clima de culpa e defesa","Comunicação truncada entre áreas","Saída de pessoas-chave"],"risks":["Aceleração da perda de clientes","Paralisia decisória"],"focus":["Restabelecer segurança psicológica e comunicação direta","Focar poucas prioridades de recuperação","Recuperar contato com clientes"]}'::jsonb);
INSERT INTO public.diag_stage_profiles (instrument_id, code, name, short_label, sort_order, axes, is_critical, auto_release_allowed, narrative) VALUES ('11111111-1111-4111-8111-000000000001', 'burocracia', 'Burocracia', 'Sistema sem propósito', 9, '{"flexibilidade":15,"controle":95,"integracao":25,"sustentacao":35}'::jsonb, true, false, '{"summary":"Fase em que regras e procedimentos substituem resultados: a empresa opera para si mesma, com baixa adaptação e pouca conexão com clientes.","signals":["Procedimentos que não geram valor","Novas ideias barradas por regras","Desconexão com o mercado"],"risks":["Dependência de proteção externa ou de caixa acumulado","Declínio acelerado quando o ambiente muda"],"focus":["Simplificar radicalmente processos","Redefinir propósito e proposta de valor","Reconstruir capacidade de decisão e adaptação"]}'::jsonb);
INSERT INTO public.diag_stage_profiles (instrument_id, code, name, short_label, sort_order, axes, is_critical, auto_release_allowed, narrative) VALUES ('11111111-1111-4111-8111-000000000001', 'declinio', 'Risco crítico de viabilidade (Declínio)', 'Risco crítico de viabilidade organizacional', 10, '{"flexibilidade":15,"controle":30,"integracao":20,"sustentacao":15}'::jsonb, true, false, '{"summary":"Sinais convergentes de risco crítico de viabilidade organizacional: fragilidade financeira, perda de clientes, ruptura cultural e baixa capacidade de reação. Exige validação humana obrigatória e leitura cuidadosa do contexto.","signals":["Resultados financeiros comprometidos","Perda de clientes e de talentos","Incapacidade de reagir a mudanças"],"risks":["Descontinuidade do negócio","Decisões emergenciais sem base"],"focus":["Avaliação imediata de caixa e viabilidade","Plano de recuperação com prioridades claras","Acompanhamento próximo do analista APAS"]}'::jsonb);
INSERT INTO public.diag_patterns (instrument_id, code, name, kind, description, severity, rule, stage_affinity, active, sort_order) VALUES ('11111111-1111-4111-8111-000000000001', 'centralizacao_no_lider', 'Centralização no líder principal', 'pattern', 'Decisões e continuidade dependem do proprietário; delegação e mecanismos de sucessão frágeis.', 'alta', '{"all":[{"type":"question","code":"L01","op":"<","value":45},{"type":"question","code":"L08","op":"<","value":50},{"type":"question","code":"PE06","op":"<","value":50}]}'::jsonb, '{"namoro":0.6,"infancia":1,"toca_toca":0.8,"adolescencia":0.2,"plenitude":-0.8,"estabilidade":-0.5,"aristocracia":-0.3,"burocracia":-0.3}'::jsonb, true, 1);
INSERT INTO public.diag_patterns (instrument_id, code, name, kind, description, severity, rule, stage_affinity, active, sort_order) VALUES ('11111111-1111-4111-8111-000000000001', 'crescimento_sem_estrutura', 'Crescimento sem estrutura', 'pattern', 'Abertura a oportunidades e mercado elevada, com processos frágeis e pouco foco.', 'alta', '{"all":[{"type":"dimension","code":"P","op":"<","value":50},{"type":"dimension","code":"M","op":">=","value":55},{"type":"question","code":"E07","op":"<","value":50}]}'::jsonb, '{"toca_toca":1,"infancia":0.5,"adolescencia":0.3,"plenitude":-0.7,"estabilidade":-0.5,"aristocracia":-0.6,"burocracia":-0.8}'::jsonb, true, 2);
INSERT INTO public.diag_patterns (instrument_id, code, name, kind, description, severity, rule, stage_affinity, active, sort_order) VALUES ('11111111-1111-4111-8111-000000000001', 'profissionalizacao_em_curso', 'Profissionalização em curso', 'pattern', 'Gestão e delegação avançam enquanto integração e tratamento de conflitos ainda amadurecem.', 'media', '{"all":[{"type":"dimension","code":"G","op":">=","value":55},{"type":"question","code":"L02","op":">=","value":55},{"type":"question","code":"C07","op":"<","value":65},{"type":"dimension","code":"CO","op":"<","value":70}]}'::jsonb, '{"adolescencia":1,"toca_toca":0.3,"plenitude":0.2,"namoro":-0.5,"burocracia":-0.4}'::jsonb, true, 3);
INSERT INTO public.diag_patterns (instrument_id, code, name, kind, description, severity, rule, stage_affinity, active, sort_order) VALUES ('11111111-1111-4111-8111-000000000001', 'equilibrio_maduro', 'Equilíbrio maduro', 'pattern', 'Todas as dimensões em nível adequado ou forte, com adaptação e sustentação simultâneas.', 'baixa', '{"all":[{"type":"axis","code":"flexibilidade","op":">=","value":70},{"type":"axis","code":"controle","op":">=","value":70},{"type":"axis","code":"integracao","op":">=","value":70},{"type":"axis","code":"sustentacao","op":">=","value":70}]}'::jsonb, '{"plenitude":1,"estabilidade":0.4,"adolescencia":0.2,"namoro":-1,"infancia":-1,"toca_toca":-0.6,"pre_burocracia":-1,"burocracia":-1,"declinio":-1}'::jsonb, true, 4);
INSERT INTO public.diag_patterns (instrument_id, code, name, kind, description, severity, rule, stage_affinity, active, sort_order) VALUES ('11111111-1111-4111-8111-000000000001', 'conforto_e_perda_de_agilidade', 'Conforto e perda de agilidade', 'pattern', 'Gestão, processos e resultados sólidos, mas baixa disposição para mudar e antecipar o mercado.', 'media', '{"all":[{"type":"dimension","code":"G","op":">=","value":60},{"type":"dimension","code":"R","op":">=","value":60},{"type":"dimension","code":"I","op":"<","value":50},{"type":"question","code":"M03","op":"<","value":50}]}'::jsonb, '{"estabilidade":1,"aristocracia":0.8,"plenitude":-0.3,"toca_toca":-1,"namoro":-0.8}'::jsonb, true, 5);
INSERT INTO public.diag_patterns (instrument_id, code, name, kind, description, severity, rule, stage_affinity, active, sort_order) VALUES ('11111111-1111-4111-8111-000000000001', 'formalismo_sem_resultado', 'Formalismo sem resultado', 'pattern', 'Controles e procedimentos fortes convivem com resultados fracos e pouca inovação.', 'alta', '{"all":[{"type":"dimension","code":"P","op":">=","value":60},{"type":"dimension","code":"R","op":"<","value":50},{"type":"dimension","code":"I","op":"<","value":45},{"type":"question","code":"C06","op":"<","value":45}]}'::jsonb, '{"aristocracia":0.6,"pre_burocracia":0.8,"burocracia":1,"plenitude":-1,"toca_toca":-0.8}'::jsonb, true, 6);
INSERT INTO public.diag_patterns (instrument_id, code, name, kind, description, severity, rule, stage_affinity, active, sort_order) VALUES ('11111111-1111-4111-8111-000000000001', 'clima_de_culpa', 'Clima de culpa e recriminação', 'pattern', 'Problemas não podem ser expostos com segurança; conflitos e busca de culpados predominam.', 'alta', '{"all":[{"type":"question","code":"C02","op":"<","value":45},{"type":"question","code":"C07","op":"<","value":45},{"type":"question","code":"L07","op":"<","value":50},{"type":"question","code":"CO06","op":"<","value":50}]}'::jsonb, '{"pre_burocracia":1,"burocracia":0.5,"declinio":0.4,"plenitude":-0.8,"estabilidade":-0.4}'::jsonb, true, 7);
INSERT INTO public.diag_patterns (instrument_id, code, name, kind, description, severity, rule, stage_affinity, active, sort_order) VALUES ('11111111-1111-4111-8111-000000000001', 'desconexao_com_mercado', 'Desconexão com o mercado', 'pattern', 'Baixa leitura de clientes e concorrentes e pouca capacidade de adaptar a oferta.', 'alta', '{"all":[{"type":"dimension","code":"M","op":"<","value":45},{"type":"question","code":"M05","op":"<","value":45},{"type":"question","code":"I03","op":"<","value":45}]}'::jsonb, '{"aristocracia":0.6,"burocracia":0.8,"declinio":0.8,"toca_toca":-0.6,"namoro":-0.3,"plenitude":-0.8}'::jsonb, true, 8);
INSERT INTO public.diag_patterns (instrument_id, code, name, kind, description, severity, rule, stage_affinity, active, sort_order) VALUES ('11111111-1111-4111-8111-000000000001', 'fragilidade_financeira', 'Fragilidade financeira', 'pattern', 'Rentabilidade, controle de custos e sustentabilidade do modelo comprometidos.', 'critica', '{"all":[{"type":"dimension","code":"R","op":"<","value":45},{"type":"question","code":"R04","op":"<","value":45},{"type":"question","code":"R07","op":"<","value":45}]}'::jsonb, '{"infancia":0.5,"declinio":1,"pre_burocracia":0.4,"namoro":0.3,"plenitude":-1,"estabilidade":-0.8,"aristocracia":-0.3}'::jsonb, true, 9);
INSERT INTO public.diag_patterns (instrument_id, code, name, kind, description, severity, rule, stage_affinity, active, sort_order) VALUES ('11111111-1111-4111-8111-000000000001', 'visao_sem_execucao', 'Visão sem execução', 'pattern', 'Clareza de propósito e diferencial, mas gestão, processos e resultados ainda incipientes.', 'media', '{"all":[{"type":"question","code":"E05","op":">=","value":60},{"type":"dimension","code":"G","op":"<","value":45},{"type":"dimension","code":"P","op":"<","value":45},{"type":"dimension","code":"R","op":"<","value":50}]}'::jsonb, '{"namoro":1,"infancia":0.5,"toca_toca":0.2,"plenitude":-0.8,"estabilidade":-0.6,"burocracia":-0.6}'::jsonb, true, 10);
INSERT INTO public.diag_patterns (instrument_id, code, name, kind, description, severity, rule, stage_affinity, active, sort_order) VALUES ('11111111-1111-4111-8111-000000000001', 'silos_internos', 'Silos internos', 'pattern', 'Informação não circula entre áreas e conflitos ficam sem tratamento.', 'media', '{"all":[{"type":"question","code":"CO04","op":"<","value":45},{"type":"question","code":"CO01","op":"<","value":50},{"type":"question","code":"C07","op":"<","value":55}]}'::jsonb, '{"adolescencia":0.7,"pre_burocracia":0.6,"burocracia":0.5,"aristocracia":0.3,"plenitude":-0.6}'::jsonb, true, 11);
INSERT INTO public.diag_patterns (instrument_id, code, name, kind, description, severity, rule, stage_affinity, active, sort_order) VALUES ('11111111-1111-4111-8111-000000000001', 'capacidade_de_adaptacao', 'Capacidade de adaptação', 'pattern', 'Empresa revisa estratégia, testa ideias e muda práticas com agilidade.', 'baixa', '{"all":[{"type":"dimension","code":"I","op":">=","value":65},{"type":"question","code":"M05","op":">=","value":60},{"type":"question","code":"E06","op":">=","value":60},{"type":"question","code":"C06","op":">=","value":60}]}'::jsonb, '{"plenitude":0.6,"toca_toca":0.5,"adolescencia":0.4,"aristocracia":-0.8,"burocracia":-1,"declinio":-0.8,"pre_burocracia":-0.6}'::jsonb, true, 12);
INSERT INTO public.diag_patterns (instrument_id, code, name, kind, description, severity, rule, stage_affinity, active, sort_order) VALUES ('11111111-1111-4111-8111-000000000001', 'dependencia_critica_do_lider', 'Dependência crítica do líder', 'critical', 'A empresa não funciona sem o líder principal e não há mecanismos para reduzir dependência de pessoas-chave.', 'alta', '{"all":[{"type":"question","code":"L08","op":"<=","value":25},{"type":"question","code":"PE06","op":"<=","value":25}]}'::jsonb, '{"infancia":0.8,"toca_toca":0.5,"namoro":0.4,"declinio":0.3,"plenitude":-0.8,"estabilidade":-0.5}'::jsonb, true, 20);
INSERT INTO public.diag_patterns (instrument_id, code, name, kind, description, severity, rule, stage_affinity, active, sort_order) VALUES ('11111111-1111-4111-8111-000000000001', 'risco_financeiro', 'Risco financeiro', 'critical', 'Crescimento não sustentável e dúvida sobre a capacidade de manter o modelo de negócio.', 'critica', '{"any":[{"type":"dimension","code":"R","op":"<","value":35},{"type":"question","code":"R07","op":"<=","value":25}]}'::jsonb, '{"declinio":1,"infancia":0.4,"pre_burocracia":0.3,"plenitude":-1,"estabilidade":-0.8,"aristocracia":-0.4}'::jsonb, true, 21);
INSERT INTO public.diag_patterns (instrument_id, code, name, kind, description, severity, rule, stage_affinity, active, sort_order) VALUES ('11111111-1111-4111-8111-000000000001', 'perda_de_conexao_com_clientes', 'Perda de conexão com clientes', 'critical', 'A empresa não acompanha necessidades, feedback nem mudanças do mercado.', 'alta', '{"all":[{"type":"question","code":"M01","op":"<=","value":25},{"type":"question","code":"M04","op":"<=","value":25},{"type":"question","code":"M03","op":"<=","value":30}]}'::jsonb, '{"declinio":0.8,"burocracia":0.6,"aristocracia":0.4,"plenitude":-0.8,"toca_toca":-0.5}'::jsonb, true, 22);
INSERT INTO public.diag_patterns (instrument_id, code, name, kind, description, severity, rule, stage_affinity, active, sort_order) VALUES ('11111111-1111-4111-8111-000000000001', 'paralisia_decisoria', 'Paralisia decisória', 'critical', 'Ideias não são testadas, mudanças não acontecem e o controle sufoca a decisão.', 'alta', '{"all":[{"type":"question","code":"I02","op":"<=","value":25},{"type":"question","code":"I03","op":"<=","value":25},{"type":"question","code":"P07","op":"<=","value":30}]}'::jsonb, '{"burocracia":1,"pre_burocracia":0.5,"aristocracia":0.4,"declinio":0.4,"plenitude":-1,"toca_toca":-0.8}'::jsonb, true, 23);
